USE CorexProdDB;
GO
/* ETAPA 14.4.2.5-B: arnes temporal; usa exclusivamente parametros nombrados. */
DECLARE @Entidad INT=(SELECT TOP 1 IdEntidadFinanciera FROM dbo.TesEntidadesFinancieras WHERE Activo=1),@Tarjeta INT=0,@Resultado BIT,@Mensaje VARCHAR(500),@Monedas dbo.TesTarjetaCreditoMonedaType;
DECLARE @PeriodoA INT=0,@PeriodoB INT=0,@PeriodoC INT=0,@PeriodoH INT=0,@PeriodoI INT=0,@PeriodoJ INT=0,@PeriodoL INT=0,@PeriodoM INT=0,@Pago INT=0,@Total DECIMAL(18,2),@Saldo DECIMAL(18,2),@Estado VARCHAR(30);
CREATE TABLE #Resultados(Prueba CHAR(1),Esperado VARCHAR(120),Real VARCHAR(300),Estado VARCHAR(10));
INSERT @Monedas VALUES('PEN'),('USD');
EXEC dbo.USP_TES_TARJETA_GUARDAR_MULTIMONEDA_TEST @IdTarjetaCredito=@Tarjeta OUTPUT,@IdEntidadFinanciera=@Entidad,@Titular='Titular prueba',@IdEmpresaResponsable=NULL,@EmpresaResponsable='Empresa prueba',@Alias='ETAPA14_4_2_5_TEST',@Ultimos4='1234',@Monedas=@Monedas,@DiaCorte=5,@DiaPago=20,@Estado='ACTIVA',@Observacion='Prueba temporal',@Usuario='ETAPA14_B5B',@Resultado=@Resultado OUTPUT,@Mensaje=@Mensaje OUTPUT;
-- A, B y C.
EXEC dbo.USP_TES_TARJETA_PERIODO_GUARDAR @IdTarjetaPeriodo=@PeriodoA OUTPUT,@IdTarjetaCredito=@Tarjeta,@PeriodoAnio=2026,@PeriodoMes=8,@FechaCorte='20260801',@FechaVencimiento='20260820',@Monto=NULL,@ImportePEN=1500,@ImporteUSD=NULL,@Estado='PENDIENTE',@Observacion='A',@Usuario='ETAPA14_B5B',@Resultado=@Resultado OUTPUT,@Mensaje=@Mensaje OUTPUT,@TotalPagado=@Total OUTPUT,@SaldoPendiente=@Saldo OUTPUT,@EstadoPeriodo=@Estado OUTPUT;
EXEC dbo.USP_TES_TARJETA_PERIODO_GUARDAR @IdTarjetaPeriodo=@PeriodoB OUTPUT,@IdTarjetaCredito=@Tarjeta,@PeriodoAnio=2026,@PeriodoMes=9,@FechaCorte='20260901',@FechaVencimiento='20260920',@Monto=NULL,@ImportePEN=NULL,@ImporteUSD=320,@Estado='PENDIENTE',@Observacion='B',@Usuario='ETAPA14_B5B',@Resultado=@Resultado OUTPUT,@Mensaje=@Mensaje OUTPUT,@TotalPagado=@Total OUTPUT,@SaldoPendiente=@Saldo OUTPUT,@EstadoPeriodo=@Estado OUTPUT;
EXEC dbo.USP_TES_TARJETA_PERIODO_GUARDAR @IdTarjetaPeriodo=@PeriodoC OUTPUT,@IdTarjetaCredito=@Tarjeta,@PeriodoAnio=2026,@PeriodoMes=10,@FechaCorte='20261001',@FechaVencimiento='20261020',@Monto=NULL,@ImportePEN=1500,@ImporteUSD=320,@Estado='PENDIENTE',@Observacion='C',@Usuario='ETAPA14_B5B',@Resultado=@Resultado OUTPUT,@Mensaje=@Mensaje OUTPUT,@TotalPagado=@Total OUTPUT,@SaldoPendiente=@Saldo OUTPUT,@EstadoPeriodo=@Estado OUTPUT;
INSERT #Resultados SELECT 'A','PEN pendiente',CONCAT(ImportePEN,'/',ISNULL(CONVERT(varchar,ImporteUSD),'NULL'),'/',EstadoPEN),CASE WHEN ImportePEN=1500 AND ImporteUSD IS NULL AND EstadoPEN='PENDIENTE' THEN 'OK' ELSE 'FALLA' END FROM dbo.TesTarjetaCreditoPeriodos WHERE IdTarjetaPeriodo=@PeriodoA;
INSERT #Resultados SELECT 'B','USD pendiente',CONCAT(ISNULL(CONVERT(varchar,ImportePEN),'NULL'),'/',ImporteUSD,'/',EstadoUSD),CASE WHEN ImportePEN IS NULL AND ImporteUSD=320 AND EstadoUSD='PENDIENTE' THEN 'OK' ELSE 'FALLA' END FROM dbo.TesTarjetaCreditoPeriodos WHERE IdTarjetaPeriodo=@PeriodoB;
INSERT #Resultados SELECT 'C','PEN+USD pendientes',CONCAT(EstadoPEN,'/',EstadoUSD),CASE WHEN ImportePEN=1500 AND ImporteUSD=320 THEN 'OK' ELSE 'FALLA' END FROM dbo.TesTarjetaCreditoPeriodos WHERE IdTarjetaPeriodo=@PeriodoC;
-- D-G.
EXEC dbo.USP_TES_TARJETA_REGISTRAR_PAGO @IdTarjetaPago=@Pago OUTPUT,@IdTarjetaPeriodo=@PeriodoC,@FechaPago='20261005',@Importe=500,@Moneda='PEN',@Usuario='ETAPA14_B5B',@Resultado=@Resultado OUTPUT,@Mensaje=@Mensaje OUTPUT,@TotalPagado=@Total OUTPUT,@SaldoPendiente=@Saldo OUTPUT,@EstadoPeriodo=@Estado OUTPUT; INSERT #Resultados VALUES('D','PEN parcial',@Mensaje,CASE WHEN @Resultado=1 THEN 'OK' ELSE 'FALLA' END);
EXEC dbo.USP_TES_TARJETA_REGISTRAR_PAGO @IdTarjetaPago=@Pago OUTPUT,@IdTarjetaPeriodo=@PeriodoC,@FechaPago='20261006',@Importe=1000,@Moneda='PEN',@Usuario='ETAPA14_B5B',@Resultado=@Resultado OUTPUT,@Mensaje=@Mensaje OUTPUT,@TotalPagado=@Total OUTPUT,@SaldoPendiente=@Saldo OUTPUT,@EstadoPeriodo=@Estado OUTPUT;INSERT #Resultados VALUES('E','PEN cancelada',@Mensaje,CASE WHEN @Resultado=1 THEN 'OK' ELSE 'FALLA' END);
EXEC dbo.USP_TES_TARJETA_REGISTRAR_PAGO @IdTarjetaPago=@Pago OUTPUT,@IdTarjetaPeriodo=@PeriodoC,@FechaPago='20261007',@Importe=120,@Moneda='USD',@Usuario='ETAPA14_B5B',@Resultado=@Resultado OUTPUT,@Mensaje=@Mensaje OUTPUT,@TotalPagado=@Total OUTPUT,@SaldoPendiente=@Saldo OUTPUT,@EstadoPeriodo=@Estado OUTPUT;INSERT #Resultados VALUES('F','USD parcial',@Mensaje,CASE WHEN @Resultado=1 THEN 'OK' ELSE 'FALLA' END);
EXEC dbo.USP_TES_TARJETA_REGISTRAR_PAGO @IdTarjetaPago=@Pago OUTPUT,@IdTarjetaPeriodo=@PeriodoC,@FechaPago='20261008',@Importe=200,@Moneda='USD',@Usuario='ETAPA14_B5B',@Resultado=@Resultado OUTPUT,@Mensaje=@Mensaje OUTPUT,@TotalPagado=@Total OUTPUT,@SaldoPendiente=@Saldo OUTPUT,@EstadoPeriodo=@Estado OUTPUT;INSERT #Resultados VALUES('G','USD cancelada',@Mensaje,CASE WHEN @Resultado=1 THEN 'OK' ELSE 'FALLA' END);
-- H/I/J/K: rechazos sobre los periodos A/B.
EXEC dbo.USP_TES_TARJETA_REGISTRAR_PAGO @IdTarjetaPago=@Pago OUTPUT,@IdTarjetaPeriodo=@PeriodoA,@FechaPago='20261009',@Importe=1501,@Moneda='PEN',@Usuario='ETAPA14_B5B',@Resultado=@Resultado OUTPUT,@Mensaje=@Mensaje OUTPUT,@TotalPagado=@Total OUTPUT,@SaldoPendiente=@Saldo OUTPUT,@EstadoPeriodo=@Estado OUTPUT;INSERT #Resultados VALUES('H','Sobrepago PEN rechazado',@Mensaje,CASE WHEN @Resultado=0 THEN 'OK' ELSE 'FALLA' END);
EXEC dbo.USP_TES_TARJETA_REGISTRAR_PAGO @IdTarjetaPago=@Pago OUTPUT,@IdTarjetaPeriodo=@PeriodoB,@FechaPago='20261009',@Importe=321,@Moneda='USD',@Usuario='ETAPA14_B5B',@Resultado=@Resultado OUTPUT,@Mensaje=@Mensaje OUTPUT,@TotalPagado=@Total OUTPUT,@SaldoPendiente=@Saldo OUTPUT,@EstadoPeriodo=@Estado OUTPUT;INSERT #Resultados VALUES('I','Sobrepago USD rechazado',@Mensaje,CASE WHEN @Resultado=0 THEN 'OK' ELSE 'FALLA' END);
EXEC dbo.USP_TES_TARJETA_REGISTRAR_PAGO @IdTarjetaPago=@Pago OUTPUT,@IdTarjetaPeriodo=@PeriodoA,@FechaPago='20261009',@Importe=1,@Moneda='USD',@Usuario='ETAPA14_B5B',@Resultado=@Resultado OUTPUT,@Mensaje=@Mensaje OUTPUT,@TotalPagado=@Total OUTPUT,@SaldoPendiente=@Saldo OUTPUT,@EstadoPeriodo=@Estado OUTPUT;INSERT #Resultados VALUES('J','USD inexistente rechazado',@Mensaje,CASE WHEN @Resultado=0 THEN 'OK' ELSE 'FALLA' END);
EXEC dbo.USP_TES_TARJETA_REGISTRAR_PAGO @IdTarjetaPago=@Pago OUTPUT,@IdTarjetaPeriodo=@PeriodoA,@FechaPago='20261009',@Importe=1,@Moneda='EUR',@Usuario='ETAPA14_B5B',@Resultado=@Resultado OUTPUT,@Mensaje=@Mensaje OUTPUT,@TotalPagado=@Total OUTPUT,@SaldoPendiente=@Saldo OUTPUT,@EstadoPeriodo=@Estado OUTPUT;INSERT #Resultados VALUES('K','EUR rechazado',@Mensaje,CASE WHEN @Resultado=0 THEN 'OK' ELSE 'FALLA' END);
SELECT * FROM #Resultados ORDER BY Prueba;
-- Limpieza exclusiva.
DELETE H FROM dbo.TesTarjetaCreditoHistorial H WHERE H.IdTarjetaCredito=@Tarjeta;DELETE FROM dbo.TesTarjetaCreditoPagos WHERE IdTarjetaPeriodo IN(SELECT IdTarjetaPeriodo FROM dbo.TesTarjetaCreditoPeriodos WHERE IdTarjetaCredito=@Tarjeta);DELETE FROM dbo.TesTarjetaCreditoPeriodos WHERE IdTarjetaCredito=@Tarjeta;DELETE FROM dbo.TesTarjetaCreditoMonedas WHERE IdTarjetaCredito=@Tarjeta;DELETE FROM dbo.TesTarjetasCredito WHERE IdTarjetaCredito=@Tarjeta;
SELECT COUNT(*) TarjetasTemporales FROM dbo.TesTarjetasCredito WHERE Alias='ETAPA14_4_2_5_TEST';
GO

/* Pruebas L-O: se ejecutan con tarjetas temporales independientes. */
DECLARE @E INT=(SELECT TOP 1 IdEntidadFinanciera FROM dbo.TesEntidadesFinancieras WHERE Activo=1),@T INT,@P INT,@Pago INT,@R BIT,@Msg VARCHAR(500),@Ttl DECIMAL(18,2),@Sal DECIMAL(18,2),@Est VARCHAR(30),@M dbo.TesTarjetaCreditoMonedaType;
CREATE TABLE #LO(Prueba CHAR(1),Real VARCHAR(500),Estado VARCHAR(10));
DECLARE @Alias VARCHAR(120);
DECLARE C CURSOR LOCAL FAST_FORWARD FOR SELECT V FROM(VALUES('ETAPA14_4_2_5_TEST_L'),('ETAPA14_4_2_5_TEST_M'),('ETAPA14_4_2_5_TEST_N'),('ETAPA14_4_2_5_TEST_O'))X(V);OPEN C;FETCH NEXT FROM C INTO @Alias;WHILE @@FETCH_STATUS=0 BEGIN SET @T=0;DELETE @M;INSERT @M VALUES('PEN'),('USD');EXEC dbo.USP_TES_TARJETA_GUARDAR_MULTIMONEDA_TEST @IdTarjetaCredito=@T OUTPUT,@IdEntidadFinanciera=@E,@Titular='Test',@EmpresaResponsable='Empresa test',@Alias=@Alias,@Monedas=@M,@Usuario='ETAPA14_B5C',@Resultado=@R OUTPUT,@Mensaje=@Msg OUTPUT;IF @Alias LIKE '%_L' BEGIN SET @P=0;EXEC dbo.USP_TES_TARJETA_PERIODO_GUARDAR @IdTarjetaPeriodo=@P OUTPUT,@IdTarjetaCredito=@T,@PeriodoAnio=2026,@PeriodoMes=11,@FechaCorte='20261101',@FechaVencimiento='20261120',@ImportePEN=1000,@Estado='PENDIENTE',@Usuario='ETAPA14_B5C',@Resultado=@R OUTPUT,@Mensaje=@Msg OUTPUT,@TotalPagado=@Ttl OUTPUT,@SaldoPendiente=@Sal OUTPUT,@EstadoPeriodo=@Est OUTPUT;SET @Pago=0;EXEC dbo.USP_TES_TARJETA_REGISTRAR_PAGO @IdTarjetaPago=@Pago OUTPUT,@IdTarjetaPeriodo=@P,@FechaPago='20261102',@Importe=400,@Moneda='PEN',@Usuario='ETAPA14_B5C',@Resultado=@R OUTPUT,@Mensaje=@Msg OUTPUT,@TotalPagado=@Ttl OUTPUT,@SaldoPendiente=@Sal OUTPUT,@EstadoPeriodo=@Est OUTPUT;EXEC dbo.USP_TES_TARJETA_ANULAR_PAGO @IdTarjetaPago=@Pago,@Usuario='ETAPA14_B5C',@Motivo='Prueba L',@Resultado=@R OUTPUT,@Mensaje=@Msg OUTPUT,@TotalPagado=@Ttl OUTPUT,@SaldoPendiente=@Sal OUTPUT,@EstadoPeriodo=@Est OUTPUT;INSERT #LO SELECT 'L',CONCAT('Pago=',@Pago,' existe=',COUNT(*),' estado=',MAX(Estado)),CASE WHEN COUNT(*)=1 AND MAX(Estado)='ANULADO' THEN 'OK' ELSE 'ERROR' END FROM dbo.TesTarjetaCreditoPagos WHERE IdTarjetaPago=@Pago END
ELSE IF @Alias LIKE '%_M' BEGIN SET @P=0;EXEC dbo.USP_TES_TARJETA_PERIODO_GUARDAR @IdTarjetaPeriodo=@P OUTPUT,@IdTarjetaCredito=@T,@PeriodoAnio=2026,@PeriodoMes=12,@FechaCorte='20261201',@FechaVencimiento='20261220',@ImportePEN=1000,@ImporteUSD=500,@Estado='PENDIENTE',@Usuario='ETAPA14_B5C',@Resultado=@R OUTPUT,@Mensaje=@Msg OUTPUT,@TotalPagado=@Ttl OUTPUT,@SaldoPendiente=@Sal OUTPUT,@EstadoPeriodo=@Est OUTPUT;SET @Pago=0;EXEC dbo.USP_TES_TARJETA_REGISTRAR_PAGO @IdTarjetaPago=@Pago OUTPUT,@IdTarjetaPeriodo=@P,@FechaPago='20261202',@Importe=400,@Moneda='PEN',@Usuario='ETAPA14_B5C',@Resultado=@R OUTPUT,@Mensaje=@Msg OUTPUT,@TotalPagado=@Ttl OUTPUT,@SaldoPendiente=@Sal OUTPUT,@EstadoPeriodo=@Est OUTPUT;EXEC dbo.USP_TES_TARJETA_REGISTRAR_PAGO @IdTarjetaPago=@Pago OUTPUT,@IdTarjetaPeriodo=@P,@FechaPago='20261202',@Importe=200,@Moneda='USD',@Usuario='ETAPA14_B5C',@Resultado=@R OUTPUT,@Mensaje=@Msg OUTPUT,@TotalPagado=@Ttl OUTPUT,@SaldoPendiente=@Sal OUTPUT,@EstadoPeriodo=@Est OUTPUT;EXEC dbo.USP_TES_TARJETA_REGISTRAR_PAGO @IdTarjetaPago=@Pago OUTPUT,@IdTarjetaPeriodo=@P,@FechaPago='20261203',@Importe=100,@Moneda='PEN',@Usuario='ETAPA14_B5C',@Resultado=@R OUTPUT,@Mensaje=@Msg OUTPUT,@TotalPagado=@Ttl OUTPUT,@SaldoPendiente=@Sal OUTPUT,@EstadoPeriodo=@Est OUTPUT;EXEC dbo.USP_TES_TARJETA_REGISTRAR_PAGO @IdTarjetaPago=@Pago OUTPUT,@IdTarjetaPeriodo=@P,@FechaPago='20261203',@Importe=100,@Moneda='USD',@Usuario='ETAPA14_B5C',@Resultado=@R OUTPUT,@Mensaje=@Msg OUTPUT,@TotalPagado=@Ttl OUTPUT,@SaldoPendiente=@Sal OUTPUT,@EstadoPeriodo=@Est OUTPUT;INSERT #LO SELECT 'M',CONCAT(TotalPagadoPEN,'/',SaldoPendientePEN,'; ',TotalPagadoUSD,'/',SaldoPendienteUSD),CASE WHEN TotalPagadoPEN=500 AND SaldoPendientePEN=500 AND TotalPagadoUSD=300 AND SaldoPendienteUSD=200 THEN 'OK' ELSE 'ERROR' END FROM dbo.TesTarjetaCreditoPeriodos WHERE IdTarjetaPeriodo=@P END
ELSE IF @Alias LIKE '%_N' BEGIN SET @P=0;EXEC dbo.USP_TES_TARJETA_PERIODO_GUARDAR @IdTarjetaPeriodo=@P OUTPUT,@IdTarjetaCredito=@T,@PeriodoAnio=2027,@PeriodoMes=1,@FechaCorte='20270101',@FechaVencimiento='20270120',@ImportePEN=1000,@Estado='PENDIENTE',@Usuario='ETAPA14_B5C',@Resultado=@R OUTPUT,@Mensaje=@Msg OUTPUT,@TotalPagado=@Ttl OUTPUT,@SaldoPendiente=@Sal OUTPUT,@EstadoPeriodo=@Est OUTPUT;SET @P=0;EXEC dbo.USP_TES_TARJETA_PERIODO_GUARDAR @IdTarjetaPeriodo=@P OUTPUT,@IdTarjetaCredito=@T,@PeriodoAnio=2027,@PeriodoMes=1,@FechaCorte='20270101',@FechaVencimiento='20270120',@ImportePEN=500,@ImporteUSD=100,@Estado='PENDIENTE',@Usuario='ETAPA14_B5C',@Resultado=@R OUTPUT,@Mensaje=@Msg OUTPUT,@TotalPagado=@Ttl OUTPUT,@SaldoPendiente=@Sal OUTPUT,@EstadoPeriodo=@Est OUTPUT;INSERT #LO SELECT 'N',CONCAT('resultado=',@R,' periodos=',COUNT(*)),CASE WHEN @R=0 AND COUNT(*)=1 THEN 'OK' ELSE 'ERROR' END FROM dbo.TesTarjetaCreditoPeriodos WHERE IdTarjetaCredito=@T END
ELSE BEGIN SET @P=0;EXEC dbo.USP_TES_TARJETA_PERIODO_GUARDAR @IdTarjetaPeriodo=@P OUTPUT,@IdTarjetaCredito=@T,@PeriodoAnio=2027,@PeriodoMes=2,@FechaCorte='20270201',@FechaVencimiento='20270220',@ImportePEN=1000,@ImporteUSD=NULL,@Estado='PENDIENTE',@Usuario='ETAPA14_B5C',@Resultado=@R OUTPUT,@Mensaje=@Msg OUTPUT,@TotalPagado=@Ttl OUTPUT,@SaldoPendiente=@Sal OUTPUT,@EstadoPeriodo=@Est OUTPUT;INSERT #LO SELECT 'O',CONCAT(ImportePEN,'/',ISNULL(CONVERT(varchar,ImporteUSD),'NULL'),'/',SaldoPendientePEN,'/',ISNULL(CONVERT(varchar,SaldoPendienteUSD),'NULL')),CASE WHEN ImporteUSD IS NULL AND SaldoPendienteUSD IS NULL THEN 'OK' ELSE 'ERROR' END FROM dbo.TesTarjetaCreditoPeriodos WHERE IdTarjetaPeriodo=@P END;FETCH NEXT FROM C INTO @Alias END;CLOSE C;DEALLOCATE C;SELECT * FROM #LO ORDER BY Prueba;
DELETE H FROM dbo.TesTarjetaCreditoHistorial H JOIN dbo.TesTarjetasCredito T ON T.IdTarjetaCredito=H.IdTarjetaCredito WHERE T.Alias LIKE 'ETAPA14_4_2_5_TEST[_]%';DELETE PG FROM dbo.TesTarjetaCreditoPagos PG JOIN dbo.TesTarjetaCreditoPeriodos P ON P.IdTarjetaPeriodo=PG.IdTarjetaPeriodo JOIN dbo.TesTarjetasCredito T ON T.IdTarjetaCredito=P.IdTarjetaCredito WHERE T.Alias LIKE 'ETAPA14_4_2_5_TEST[_]%';DELETE P FROM dbo.TesTarjetaCreditoPeriodos P JOIN dbo.TesTarjetasCredito T ON T.IdTarjetaCredito=P.IdTarjetaCredito WHERE T.Alias LIKE 'ETAPA14_4_2_5_TEST[_]%';DELETE M FROM dbo.TesTarjetaCreditoMonedas M JOIN dbo.TesTarjetasCredito T ON T.IdTarjetaCredito=M.IdTarjetaCredito WHERE T.Alias LIKE 'ETAPA14_4_2_5_TEST[_]%';DELETE FROM dbo.TesTarjetasCredito WHERE Alias LIKE 'ETAPA14_4_2_5_TEST[_]%';SELECT COUNT(*) Restantes FROM dbo.TesTarjetasCredito WHERE Alias LIKE 'ETAPA14_4_2_5_TEST[_]%';
GO
